{
  "summary": [
    {
      "text": "Безразмерные переменные позволяют упростить задачу, объединяя координату, время и свойства пласта в один параметр.",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "Введение автомодельной переменной $u$ сводит зависимость давления от трёх величин к зависимости от одной.",
      "claims": [
        "c2"
      ]
    }
  ],
  "how_it_works": [
    {
      "text": "Безразмерное давление $P$ определяется как отношение изменения давления к разности давлений на границах.",
      "claims": [
        "c3"
      ]
    },
    {
      "text": "Изначально $P$ зависит от координаты $x$, времени $t$ и коэффициента пьезопроводности $\\kappa$.",
      "claims": [
        "c4"
      ]
    },
    {
      "text": "Анализ размерностей показывает, что из $x$, $t$ и $\\kappa$ можно составить безразмерный комплекс $x/\\sqrt{\\kappa t}$.",
      "claims": [
        "c5"
      ]
    },
    {
      "text": "Вводится новая переменная $u = x/(2\\sqrt{\\kappa t})$, называемая автомодельной переменной.",
      "claims": [
        "c6"
      ]
    },
    {
      "text": "После замены переменных давление $P$ зависит только от $u$, то есть $P = f(u)$.",
      "claims": [
        "c7"
      ]
    },
    {
      "text": "Граничные условия переписываются через новую переменную: $P=0$ при $u=0$ и $P=1$ при $u=\\infty$.",
      "claims": [
        "c8"
      ]
    }
  ],
  "steps": [
    {
      "text": "Определяется безразмерное давление $P$ через физические давления.",
      "claims": [
        "c3"
      ]
    },
    {
      "text": "Устанавливается исходная зависимость $P$ от $x, t, \\kappa$.",
      "claims": [
        "c4"
      ]
    },
    {
      "text": "Анализируются размерности аргументов для поиска безразмерного комплекса.",
      "claims": [
        "c5"
      ]
    },
    {
      "text": "Вводится автомодельная переменная $u$ на основе найденного комплекса.",
      "claims": [
        "c6"
      ]
    },
    {
      "text": "Задача сводится к поиску функции $P(u)$.",
      "claims": [
        "c7"
      ]
    },
    {
      "text": "Формулируются граничные условия в новых переменных.",
      "claims": [
        "c8"
      ]
    }
  ],
